package br.com.axecloud.app.feature.care
import androidx.lifecycle.*
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import javax.inject.Inject
@HiltViewModel class CareViewModel @Inject constructor(private val repo:CareRepository):ViewModel(){private val mutable=MutableStateFlow(CareUiState());val state=mutable.asStateFlow();init{load()};fun load()=viewModelScope.launch{mutable.update{it.copy(loading=true,error=null)};runCatching{repo.load()}.onSuccess{r->mutable.update{it.copy(loading=false,requests=r,selected=it.selected?.let{s->r.find{n->n.id==s.id}})}}.onFailure{e->mutable.update{it.copy(loading=false,error=e.message)}}};fun query(v:String)=mutable.update{it.copy(query=v)};fun filter(v:String)=mutable.update{it.copy(filter=v)};fun select(v:PrayerRequest?)=mutable.update{it.copy(selected=v)};fun consume()=mutable.update{it.copy(message=null)};fun update(r:PrayerRequest,status:String,note:String?=null)=viewModelScope.launch{mutable.update{it.copy(actionId=r.id,error=null)};runCatching{repo.update(r.id,status,note)}.onSuccess{n->mutable.update{it.copy(actionId=null,requests=if(status=="concluido")it.requests.filterNot{x->x.id==r.id}else it.requests.map{x->if(x.id==n.id)n else x},selected=if(status=="concluido")null else n,message=statusMessage(status))}}.onFailure{e->mutable.update{it.copy(actionId=null,error=e.message)}}};private fun statusMessage(s:String)=when(s){"aceito"->"Pedido acolhido. O fiel será avisado.";"em_oracao"->"Reza iniciada.";"concluido"->"Atendimento concluído e arquivado.";else->"Atendimento atualizado."}}
